def semantic_rows(value):
    if isinstance(value,list):
        return value
    if isinstance(value,dict):
        rows=value.get('answers')
        if isinstance(rows,list):
            return rows
        if isinstance(rows,dict):
            return list(rows.values())
        return list(value.values())
    return []

def has_semantic_answer(rows,qid):
    for row in rows:
        if isinstance(row,dict) and row.get('id')==qid:
            return True
    return False

def ordered_unit_ids(spans):
    out=[]
    for span in spans:
        if isinstance(span,dict):
            uid=span.get('id')
            if uid not in out:
                out.append(uid)
    return out

def apply(inputs,premises):
    if inputs.get('phase')!='plan':
        return {'queries':[]}
    unit_ids=ordered_unit_ids(inputs.get('source_spans',[]))
    if not unit_ids:
        return {'queries':[]}
    rows=semantic_rows(inputs.get('semantic_answers',[]))
    specs=[
        ('maud_knowledge_structure_v1_all_units','read_knowledge_definition_structure_v1'),
        ('maud_knowledge_exclusion_v1_all_units','read_knowledge_inquiry_exclusion_v1'),
        ('maud_pandemic_binding_v1_all_units','read_interim_covenant_pandemic_binding_v1')
    ]
    queries=[]
    for qid,operation in specs:
        if not has_semantic_answer(rows,qid):
            queries.append({'id':qid,'operation':operation,'unit_ids':list(unit_ids)})
    return {'queries':queries}
